export interface Request {
  readonly method: string;
  readonly path: string;
  readonly body: Buffer;
}

export interface Response {
  readonly status: number;
  readonly headers?: Readonly<Record<string, string>>;
  readonly body?: Buffer | string;
}

export type Handler = (request: Request) => Response;

export const emptyResponse = (status: number): Response => ({ status });

export const textResponse = (status: number, body: string): Response => ({
  status,
  headers: { 'Content-Type': 'text/plain; charset=utf-8' },
  body,
});

export type PutResult = 'created' | 'replaced';

/** In-memory key-value store holding raw byte values. */
export class KvStore {
  readonly #data = new Map<string, Buffer>();

  put(key: string, value: Buffer): PutResult {
    const existed = this.#data.has(key);
    this.#data.set(key, value);
    return existed ? 'replaced' : 'created';
  }

  get(key: string): Buffer | undefined {
    return this.#data.get(key);
  }

  delete(key: string): boolean {
    return this.#data.delete(key);
  }

  /** All keys, sorted ascending by byte value (keys are ASCII). */
  keys(): string[] {
    return [...this.#data.keys()].sort();
  }
}

import { KvStore } from './kvStore.ts';
import { route } from './routes.ts';
import { startServer } from './server.ts';

function parsePort(arg: string | undefined): number | undefined {
  if (arg === undefined || !/^\d{1,5}$/.test(arg)) return undefined;
  const port = Number(arg);
  return port >= 1 && port <= 65535 ? port : undefined;
}

const args = process.argv.slice(2);
if (args.length !== 1) {
  console.error('usage: app <port>');
  process.exit(2);
}
const port = parsePort(args[0]);
if (port === undefined) {
  console.error(`invalid port: ${args[0]}`);
  process.exit(2);
}

const store = new KvStore();
try {
  await startServer({ port }, (request) => route(store, request));
} catch (error) {
  console.error('fatal:', error instanceof Error ? error.message : error);
  process.exit(1);
}

import { emptyResponse, textResponse, type Request, type Response } from './http.ts';
import type { KvStore } from './kvStore.ts';

const KV_PREFIX = '/kv/';
const KEY_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;

export const isValidKey = (key: string): boolean => KEY_PATTERN.test(key);

const methodNotAllowed = (allow: string): Response => ({
  ...textResponse(405, 'Method Not Allowed'),
  headers: { 'Content-Type': 'text/plain; charset=utf-8', Allow: allow },
});

const notFound = (): Response => textResponse(404, 'not found');

function handleHealth(request: Request): Response {
  return request.method === 'GET' ? textResponse(200, 'ok') : methodNotAllowed('GET');
}

function handleList(store: KvStore, request: Request): Response {
  if (request.method !== 'GET') return methodNotAllowed('GET');
  return {
    status: 200,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(store.keys()),
  };
}

function handleKey(store: KvStore, request: Request, key: string): Response {
  if (!isValidKey(key)) return textResponse(400, 'invalid key');

  switch (request.method) {
    case 'GET': {
      const value = store.get(key);
      return value
        ? { status: 200, headers: { 'Content-Type': 'application/octet-stream' }, body: value }
        : notFound();
    }
    case 'PUT':
      return emptyResponse(store.put(key, request.body) === 'created' ? 201 : 200);
    case 'DELETE':
      return store.delete(key) ? emptyResponse(204) : notFound();
    default:
      return methodNotAllowed('GET, PUT, DELETE');
  }
}

/** Dispatches a request to the matching route. */
export function route(store: KvStore, request: Request): Response {
  const { path } = request;
  if (path === '/health') return handleHealth(request);
  if (path === '/kv') return handleList(store, request);
  if (path.startsWith(KV_PREFIX)) return handleKey(store, request, path.slice(KV_PREFIX.length));
  return notFound();
}

import http, { type IncomingMessage, type ServerResponse } from 'node:http';
import { textResponse, type Handler, type Response } from './http.ts';

export interface ServerOptions {
  readonly port: number;
  readonly host?: string;
  readonly maxHeadBytes?: number;
  readonly maxBodyBytes?: number;
  readonly ioTimeoutMs?: number;
}

class HttpError extends Error {
  readonly status: number;

  constructor(status: number) {
    super(http.STATUS_CODES[status] ?? 'Error');
    this.status = status;
  }
}

/** Collects the request body, rejecting with 413 once it exceeds `limit` bytes. */
function readBody(req: IncomingMessage, limit: number): Promise<Buffer> {
  const declared = req.headers['content-length'];
  if (declared !== undefined && Number(declared) > limit) {
    return Promise.reject(new HttpError(413));
  }
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    const onData = (chunk: Buffer): void => {
      size += chunk.length;
      if (size > limit) {
        req.off('data', onData);
        reject(new HttpError(413));
        return;
      }
      chunks.push(chunk);
    };
    req.on('data', onData);
    req.once('end', () => resolve(Buffer.concat(chunks, size)));
    req.once('error', reject);
  });
}

function send(req: IncomingMessage, res: ServerResponse, response: Response): void {
  const body = response.body ?? '';
  res.statusCode = response.status;
  for (const [name, value] of Object.entries(response.headers ?? {})) {
    res.setHeader(name, value);
  }
  if (response.status !== 204) {
    res.setHeader('Content-Length', Buffer.byteLength(body));
  }
  res.setHeader('Connection', 'close');
  // Keep draining any unread request bytes so the client sees the response
  // rather than a connection reset.
  req.resume();
  res.end(response.status === 204 ? undefined : body);
}

/** Starts an HTTP/1.1 server that serves every request through `handler`. */
export function startServer(options: ServerOptions, handler: Handler): Promise<http.Server> {
  const maxBodyBytes = options.maxBodyBytes ?? 1024 * 1024;
  const ioTimeoutMs = options.ioTimeoutMs ?? 10_000;

  const server = http.createServer(
    { maxHeaderSize: options.maxHeadBytes ?? 64 * 1024, keepAlive: false },
    (req, res) => {
      readBody(req, maxBodyBytes).then(
        (body) => {
          let response: Response;
          try {
            response = handler({ method: req.method ?? '', path: req.url ?? '', body });
          } catch (error) {
            console.error('handler error:', error);
            response = textResponse(500, 'Internal Server Error');
          }
          send(req, res, response);
        },
        (error: unknown) => {
          const status = error instanceof HttpError ? error.status : 400;
          send(req, res, textResponse(status, http.STATUS_CODES[status] ?? 'Error'));
        },
      );
    },
  );
  server.headersTimeout = ioTimeoutMs;
  server.requestTimeout = ioTimeoutMs * 3;
  server.keepAliveTimeout = 0;

  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(options.port, options.host ?? '127.0.0.1', () => {
      server.off('error', reject);
      resolve(server);
    });
  });
}
